{
  "pou_name": "FB_AutomatedFillingLine",
  "pou_type": "FUNCTION_BLOCK",
  "declaration": "FUNCTION_BLOCK FB_AutomatedFillingLine
    VAR_INPUT
        bottleSensor : BOOL;
        cleaningConfirmButton : BOOL;
        fillingConfirmButton : BOOL;
        cappingConfirmButton : BOOL;
        packingConfirmButton : BOOL;
        finishedButton : BOOL;
    END_VAR

    VAR_OUTPUT
        Pump_Motor : BOOL;
        Filling_Valve : BOOL;
        Capping_Machine : BOOL;
        Packing_Machine : BOOL;
        Completion_Light : BOOL;
    END_VAR

    VAR
        state : INT := 0;
    END_VAR
END_FUNCTION_BLOCK",
  "implementation": "CASE state OF
    0: (* Waiting for bottle *)
        Pump_Motor := bottleSensor;
        IF bottleSensor THEN
            state := 1;
        END_IF;

    1: (* Cleaning *)
        Pump_Motor := TRUE;
        IF cleaningConfirmButton THEN
            state := 2;
        END_IF;

    2: (* Filling *)
        Pump_Motor := FALSE;
        Filling_Valve := TRUE;
        IF fillingConfirmButton THEN
            state := 3;
        END_IF;

    3: (* Capping *)
        Filling_Valve := FALSE;
        Capping_Machine := TRUE;
        IF cappingConfirmButton THEN
            state := 4;
        END_IF;

    4: (* Packaging *)
        Capping_Machine := FALSE;
        Packing_Machine := TRUE;
        IF packingConfirmButton THEN
            state := 5;
        END_IF;

    5: (* Completion *)
        Packing_Machine := FALSE;
        Completion_Light := TRUE;
        IF finishedButton THEN
            state := 0;
        END_IF;

    ELSE
        state := 0;
END_CASE;"
}
